Dataspatium.assets.register("presets/api/statfin-geo.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"statfin-geo\",\n  \"name\": \"Statistikcentralen geodata (WFS)\",\n  \"publisher\": \"Statistikcentralen\",\n  \"description\": \"Statistikområden från Statistikcentralen som geodata: kommuner, landskap, postnummerområden, rutnät med befolkning med mera. Välj lager och hämta objekten med geometri.\",\n  \"docs\": \"https://www.stat.fi/org/avoindata/paikkatietoaineistot_sv.html\",\n  \"license\": {\n    \"name\": \"CC BY 4.0\",\n    \"url\": \"https://creativecommons.org/licenses/by/4.0/\"\n  },\n  \"level\": 1,\n  \"country\": \"FI\",\n  \"baseUrl\": \"https://geo.stat.fi/geoserver/wfs\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"wfs\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren hämtas från tjänsten när källan öppnas (GetCapabilities respektive tjänstekatalogen). Svaren är GeoJSON i WGS 84 och öppnas som kartor.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Statistics Finland geodata (WFS)\",\n      \"description\": \"Statistical areas from Statistics Finland as geodata: municipalities, regions, postal code areas, population grids and more. Choose a layer and fetch the features with geometry.\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities or the service directory). Answers are GeoJSON in WGS 84 and open as maps.\"\n    },\n    \"da\": {\n      \"name\": \"Statistikcentralen geodata (WFS)\",\n      \"description\": \"Statistiske områder fra Statistikcentralen som geodata: kommuner, landskaber, postnummerområder, befolkningsgitre med mere. Vælg et lag og hent objekterne med geometri.\",\n      \"notes\": \"Lagene hentes fra tjenesten, når kilden åbnes (GetCapabilities henholdsvis tjenestekataloget). Svarene er GeoJSON i WGS 84 og åbnes som kort.\"\n    },\n    \"nb\": {\n      \"name\": \"Statistikcentralen geodata (WFS)\",\n      \"description\": \"Statistiske områder fra Statistikcentralen som geodata: kommuner, landskap, postnummerområder, befolkningsrutenett med mer. Velg lag og hent objektene med geometri.\",\n      \"notes\": \"Lagene hentes fra tjenesten når kilden åpnes (GetCapabilities respektive tjenestekatalogen). Svarene er GeoJSON i WGS 84 og åpnes som kart.\"\n    },\n    \"fi\": {\n      \"name\": \"Tilastokeskus paikkatieto (WFS)\",\n      \"description\": \"Tilastoalueet Tilastokeskukselta paikkatietona: kunnat, maakunnat, postinumeroalueet, väestöruudukot ja muuta. Valitse taso ja nouda kohteet geometrioineen.\",\n      \"notes\": \"Tasot noudetaan palvelusta, kun lähde avataan (GetCapabilities tai palveluhakemisto). Vastaukset ovat GeoJSONia WGS 84:ssä ja avautuvat karttoina.\"\n    },\n    \"is\": {\n      \"name\": \"Landupplýsingar Hagstofu Finnlands (WFS)\",\n      \"description\": \"Hagskýrslusvæði frá Hagstofu Finnlands sem landupplýsingar: sveitarfélög, landshlutar, póstnúmerasvæði, mannfjöldareitir og fleira. Veldu lag og sæktu fitjurnar með rúmfræði.\",\n      \"notes\": \"Lögin eru sótt úr þjónustunni þegar uppsprettan er opnuð (GetCapabilities eða þjónustuskráin). Svörin eru GeoJSON í WGS 84 og opnast sem kort.\"\n    }\n  }\n}\n");
